'use strict';
const root=document.querySelector('#app'),dialog=document.querySelector('#auth');
const state={page:'library',situations:[],sessions:[],legacySessions:[],progress:[],progressRevision:0,progressClearRevision:0,progressFetchSequence:0,progressAppliedSequence:0,progressChanges:new Map(),config:{},user:null,ownerId:null,ownerEpoch:0,csrf:'',profile:{},query:'',level:'all',situation:null,mission:null,session:null,transcript:'',originalTranscript:'',voiceEdited:false,support:[],error:'',notice:'',busy:false,operation:null,recorder:null,stream:null,pendingAudio:null,audio:null,audioUrl:null,hint:false,english:false,answers:{},authMode:'login',authError:'',recoveryCodes:[]};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cap=x=>x?x[0].toUpperCase()+x.slice(1):'';
const displaySupports=items=>Array.isArray(items)&&items.length?items.map(item=>item==='learner_confirmation'?'meaning you selected':item).join(', '):'none recorded';
const sceneBrief=x=>'In this scene: '+String(x||'').replace(/^Fictional task facts:\s*/i,'').replace('Use fictional names, codes and addresses. No real booking or purchase is made.','').replace(/\s{2,}/g,' ').trim();
function safeLink(value){try{const url=new URL(value);return url.protocol==='https:'?url.href:'#'}catch{return '#'}}
const ids=new Map();function requestId(key,body){const sig=JSON.stringify(body),old=ids.get(key);if(old&&old.sig===sig)return old.id;const id=crypto.randomUUID();ids.set(key,{sig,id});return id}
function authView(){const mode=state.authMode;dialog.querySelector('#auth-content').innerHTML=`<form id="auth-form"><h2 id="auth-title">${mode==='register'?'Create your account':mode==='recover'?'Recover your account':'Sign in'}</h2><p class="small">${mode==='register'?'Use your invitation. Choose a username of 3–64 letters, numbers, dots, dashes or underscores and a password of at least 12 characters.':mode==='recover'?'Use a recovery code and set a new password of at least 12 characters.':'Your practice stays with your account.'}</p>${state.authError?`<p class="notice" role="status">${esc(state.authError)}</p>`:''}<label class="field">Username<input name="username" autocomplete="username" required></label>${mode==='register'?'<label class="field">Invitation<input name="invite" autocomplete="off" required></label>':''}${mode==='recover'?'<label class="field">Recovery code<input name="recovery_code" autocomplete="off" required></label>':''}<label class="field">${mode==='recover'?'New password':'Password'}<input type="password" name="password" autocomplete="${mode==='login'?'current-password':'new-password'}" required></label><button class="btn" type="submit">${mode==='register'?'Create account':mode==='recover'?'Reset password':'Sign in'}</button><button type="button" class="btn secondary" data-auth-mode="${mode==='login'?'register':'login'}">${mode==='login'?'Have an invitation? Create account':'Back to sign in'}</button>${mode==='login'?'<button type="button" class="textbtn" data-auth-mode="recover">Use a recovery code</button>':''}</form>`;if(!dialog.open)dialog.showModal()}
function showRecovery(codes){state.recoveryCodes=codes;dialog.querySelector('#auth-content').innerHTML=`<div class="stack"><h2 id="auth-title">Save your recovery codes</h2><p class="small">Store these somewhere safe. Each code can be used once to recover your account.</p><div class="card">${codes.map(x=>`<code>${esc(x)}</code>`).join('')}</div><button class="btn" data-action="recovery-done">I saved these</button></div>`;if(!dialog.open)dialog.showModal()}
async function request(path,options={}){const epoch=state.ownerEpoch;const signal=options.signal||state.operation?.controller.signal,headers=new Headers(options.headers||{});if(options.method&&options.method!=='GET'&&state.csrf)headers.set('X-CSRF-Token',state.csrf);let r;try{r=await fetch(path,{...options,headers,signal,credentials:'same-origin',cache:'no-store'})}catch(e){if(signal?.aborted||e.name==='AbortError')throw e;throw Error('The service is unreachable. Check your connection and try again. Your draft is still here.')}if(signal?.aborted||epoch!==state.ownerEpoch)throw new DOMException('Stopped waiting','AbortError');if(r.status===401&&path!=='api/account'&&path!=='api/auth/recovery-codes'){state.authError='Your session ended. Sign in and retry; your draft is still here.';state.authMode='login';state.user=null;authView();throw Error(state.authError)}return r}
async function api(path,options={}){const epoch=state.ownerEpoch;const signal=options.signal||state.operation?.controller.signal;const r=await request(path,options),d=await r.json().catch(()=>({}));if(signal?.aborted||epoch!==state.ownerEpoch)throw new DOMException('Stopped waiting','AbortError');if(!r.ok){const error=Error(d.error||d.detail||(r.status>=500?'The practice service is temporarily unavailable. Please retry; your draft is still here.':`Request failed (${r.status}).`));error.status=r.status;throw error}return d}
const post=(path,body)=>api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
async function run(fn){if(state.busy)return;const op={controller:new AbortController()};state.operation=op;state.busy=true;state.error='';render();try{await fn()}catch(e){if(state.operation===op&&e.name!=='AbortError')state.error=e.message}finally{if(state.operation===op){state.operation=null;state.busy=false;render()}}}
function stopAudio(){if(state.audio)state.audio.pause();state.audio=null;if(state.audioUrl)URL.revokeObjectURL(state.audioUrl);state.audioUrl=null;state.audioNeedsTap=false;state.audioPlaying=false;state.audioKind=null}
function stopCapture(){const r=state.recorder;if(!r)return;r.discard=true;clearTimeout(state.recordingTimer);if(r.state!=='inactive')r.stop();state.stream?.getTracks().forEach(t=>t.stop());state.recorder=null;state.stream=null}
function go(page){if(state.page!==page){stopAudio();stopCapture()}state.page=page;state.error='';state.notice='';render();root.focus({preventScroll:true});window.scrollTo(0,0)}
function cancel(){if(!state.operation)return;if(state.audioJob){const job=state.audioJob;fetch(`api/audio/jobs/${encodeURIComponent(job)}`,{method:'DELETE',credentials:'same-origin',headers:{'X-CSRF-Token':state.csrf},cache:'no-store'}).catch(()=>{});state.audioJob=null}state.operation.controller.abort();stopAudio();state.operation=null;state.busy=false;state.error='Stopped waiting. The server may still finish and save this request. Check your practice before retrying.';render()}
function error(){return state.error?`<div class="notice" role="status">${esc(state.error)}</div>`:state.notice?`<div class="card" role="status">${esc(state.notice)}</div>`:''}
function render(){const active=document.activeElement,keepDraftFocus=active?.id==='transcript'&&root.contains?.(active),selectionStart=keepDraftFocus?active.selectionStart:null,selectionEnd=keepDraftFocus?active.selectionEnd:null;document.querySelectorAll('[data-nav]').forEach(b=>{b.disabled=state.busy;const active=b.dataset.nav===state.page||b.dataset.nav==='library'&&['situation','practice','complete','followup'].includes(state.page);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});const views={library,situation,practice,complete,followup,history,profile};root.innerHTML=(state.busy?'<div class="notice">Working… <button class="textbtn" data-action="cancel">Stop waiting</button><br>The server may still finish. Check saved practice before retrying.</div>':'')+(state.audio?`<div class="card" role="status"><span class="small">${state.audioNeedsTap?'Audio is ready. Tap Play audio to listen.':state.audioPlaying?'Audio is playing.':'Audio is ready to replay.'}</span><div class="actions"><button data-action="play-cached">▶ Play audio</button><button data-action="stop-audio">■ Stop audio</button></div></div>`:'')+(views[state.page]||library)();if(keepDraftFocus){const input=document.querySelector('#transcript');if(input){input.focus({preventScroll:true});if(selectionStart!==null&&selectionEnd!==null)input.setSelectionRange?.(selectionStart,selectionEnd)}}if(state.scrollAfterTurn){state.scrollAfterTurn=false;if(!keepDraftFocus){const reduce=window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;document.querySelector('#latest-reply')?.scrollIntoView?.({block:'start',behavior:reduce?'auto':'smooth'})}}}
function library(){const rows=state.situations.filter(x=>(state.level==='all'||x.level===state.level)&&`${x.title} ${x.description}`.toLowerCase().includes(state.query.toLowerCase()));return `<div class="eyebrow">Prata · Swedish practice</div><h1>Make room to speak.</h1><p class="sub">Choose a situation, then a task that matters to you. Each guided conversation gives you a reason to use Swedish.</p><div class="notice">Check the transcript before sending. Tasks track your practice; they do not award SFI grades.</div><label class="field">Find a situation<input id="search" type="search" value="${esc(state.query)}" placeholder="Search situations"></label><div class="pillrow" role="group" aria-label="Conversation challenge">${['all','basic','medium','high'].map(v=>`<button class="pill" data-level="${v}" aria-pressed="${state.level===v}">${v==='all'?'All':cap(v)}</button>`).join('')}</div><p class="tiny">Challenge describes the task, not your SFI course. High tasks are guided discussions.</p>${error()}${rows.length?rows.map(s=>`<button class="scenario" data-situation="${esc(s.id)}"><span class="iconbubble" aria-hidden="true">${s.level==='basic'?'☕':s.level==='medium'?'⌂':'✳'}</span><span class="grow"><span class="tiny">${esc(cap(s.level))} · ${(s.missions||[]).length} tasks</span><strong>${esc(s.title)}</strong><span class="small">${esc(s.description)}</span></span><span class="chev" aria-hidden="true">›</span></button>`).join(''):'<div class="card empty"><strong>No situations found</strong><p class="small">Try another search or challenge.</p></div>'}`}
function situation(){const s=state.situation;if(!s)return '';return `<button class="back" data-action="library">← All situations</button><span class="tag">${esc(cap(s.level))}${s.level==='high'?' · Guided discussion':''}</span><h1>${esc(s.title)}</h1><p class="sub">${esc(s.description)}</p><h2 class="section-title">Choose a task</h2><p class="small">Each task has its own goal and conversation.</p>${error()}${(s.missions||[]).map((m,i)=>`<button class="scenario" data-mission="${esc(m.id)}"><span class="iconbubble">${i+1}</span> <span class="grow"><strong>${esc(m.title)}</strong> <span class="small">${esc(m.goal)}</span> ${m.learner_brief_en?`<span class="small">${esc(sceneBrief(m.learner_brief_en))}</span>`:''}</span><span class="chev" aria-hidden="true">›</span></button>`).join('')}`}
function suggestedPhrases(session){const step=session?.snapshot?.mission?.steps?.find(x=>x.id===session.current_step);const seen=new Set();return (step?.intents||[]).map(i=>(i.examples_sv||[]).find(x=>typeof x==='string'&&x.trim())).filter(Boolean).map(x=>x.trim()).filter(x=>{const key=x.toLocaleLowerCase('sv');if(seen.has(key))return false;seen.add(key);return true})}
function unmatchedMarker(session){const turns=session?.turns||[],index=turns.length-2,user=turns[index],reply=turns[index+1];if(index<0||session.status==='completed'||user?.role!=='user'||typeof user.turn_id!=='string'||!user.turn_id||user.intent_id!==null||user.clarified||user.step_id!==session.current_step||reply?.role!=='assistant'||reply.matched!==false)return null;return {session:session.id,step:session.current_step,turnIndex:index,turnId:user.turn_id,ownerEpoch:state.ownerEpoch}}
function validUnmatched(marker,session){return !!(marker&&session&&state.page==='practice'&&marker.session===session.id&&marker.step===session.current_step&&marker.ownerEpoch===state.ownerEpoch)}
function unmatchedGuidance(session){const marker=state.unmatched;if(!validUnmatched(marker,session))return '';const step=session.snapshot?.mission?.steps?.find(x=>x.id===session.current_step);const intents=(step?.intents||[]).filter(i=>i.id&&i.meaning_en&&i.meaning_sv),phrases=suggestedPhrases(session);const confirm=Number.isInteger(marker.turnIndex)&&marker.turnIndex>=0&&intents.length?`<div class="card"><strong>What did you mean?</strong><p class="small">Choose the meaning you intended. Your original reply stays saved; your choice is recorded as supported practice, not a grade or automatic correction.</p>${intents.map(intent=>`<button class="scenario meaning-choice" data-confirm-intent="${esc(intent.id)}" data-confirm-session="${esc(session.id)}" data-confirm-step="${esc(session.current_step)}" data-confirm-turn="${marker.turnIndex}" data-confirm-turn-id="${esc(marker.turnId)}" data-confirm-epoch="${state.ownerEpoch}"><span class="grow"><strong>${esc(intent.meaning_en)}</strong><span class="small" lang="sv">${esc(intent.meaning_sv)}</span></span></button>`).join('')}</div>`:'';const retry=phrases.length?`<details class="task-details"><summary>Try a suggested phrase instead</summary><p class="small">You can also try again in your own words, or choose a phrase to edit before sending.</p>${phrases.map((phrase,i)=>`<div class="suggested-phrase"><span lang="sv">${esc(phrase)}</span><button class="pill" data-guidance-index="${i}" data-guidance-session="${esc(session.id)}" data-guidance-step="${esc(session.current_step)}" data-guidance-epoch="${state.ownerEpoch}" aria-label="Use phrase ${esc(phrase)}">Use this phrase</button></div>`).join('')}</details>`:'';return confirm+retry}
function confirmedMeaning(session,turn){if(!turn.clarified&&!turn.confirmed_intent_id)return '';const intent=session.snapshot?.mission?.steps?.find(s=>s.id===turn.step_id)?.intents?.find(i=>i.id===turn.confirmed_intent_id);return intent?.meaning_en||turn.confirmed_intent_id||''}
function practice(){const s=state.session,m=s?.snapshot?.mission||state.mission;if(!s||!m)return '';const done=s.completed_objectives||[],steps=m.steps||[],turns=s.turns||[];let latestAssistant=-1;for(let i=turns.length-1;i>=0;i--)if(turns[i].role==='assistant'){latestAssistant=i;break}return `<button class="back" data-action="situation">← Tasks</button><span class="tag">${esc(cap(state.situation?.level||''))}${state.situation?.level==='high'?' · Guided discussion':''}</span><h1>${esc(m.title)}</h1><p class="small">${esc(m.goal)}</p>${m.learner_brief_en?`<p class="small">${esc(sceneBrief(m.learner_brief_en))}</p>`:''}<div class="split"><span class="tiny">${done.length} of ${(m.completion_objectives||[]).length} task goals practised</span></div><details id="task-details" class="task-details" ${state.taskDetailsOpen?'open':''}><summary>Task details</summary><p class="small">Use fictional details for practice.</p>${m.response_guidance_en?`<p class="small">${esc(m.response_guidance_en)}</p>`:''}<ul class="objectives">${(m.completion_objectives||[]).map(id=>`<li>${done.includes(id)?'✓':'○'} ${esc((steps.find(step=>step.objective===id)||{}).objective_label||id)}</li>`).join('')}</ul></details><div class="messages" aria-live="polite">${turns.map((t,i)=>`<div${i===latestAssistant?' id="latest-reply"':''} class="message ${t.role==='user'?'mine':''}"><strong>${t.role==='user'?'You':esc(m.character?.name||'Your conversation partner')}</strong>${esc(t.text)}${t.role==='user'&&confirmedMeaning(s,t)?`<p class="tiny">Meaning you selected: ${esc(confirmedMeaning(s,t))} · supported practice</p>`:''}${t.role!=='user'?`<div class="actions"><button data-speak="${i}">▶ Listen</button><button data-speak="${i}" data-slow="true">▶ Slow</button></div>`:''}</div>`).join('')}</div>${state.feedback?`<div class="card"><strong>Try next</strong><p class="small">${esc(state.feedback)}</p></div>`:''}${unmatchedGuidance(s)}${state.english?`<div class="card"><strong>Opening in English</strong><p>${esc(m.opening_en)}</p></div>`:''}${state.hint?`<div class="card"><strong>Helpful phrases</strong>${(m.phrases||[]).map(p=>`<span>${esc(p.sv)} <span class="small">— ${esc(p.en)}</span></span>`).join('')}</div>`:''}<div class="actions"><button data-action="hint">${state.hint?'Hide hint':'Need a hint?'}</button><button data-action="english">${state.english?'Hide English':'English help'}</button></div><div id="composer" class="composer"><div class="mic-wrap"><button class="mic ${state.recorder?'recording':''}" data-action="mic" aria-label="${state.recorder?'Stop recording':'Start recording'}">${state.recorder?'■':'🎙'}</button><div class="mic-copy"><div class="mic-label">${state.recorder?'Tap to stop recording':'Tap to speak · tap again to stop'}</div><p class="tiny">Review your words before sending.</p></div></div>${state.pendingAudio?'<button class="btn secondary" data-action="transcribe">Retry transcription</button>':''}<label class="field">Your Swedish words<textarea id="transcript" placeholder="Type here, or use the microphone">${esc(state.transcript)}</textarea></label>${error()}<button class="btn" data-action="send">Send message</button></div>`}
function complete(){const m=state.session?.snapshot?.mission||state.mission,s=state.situation;const candidates=(s?.missions||[]).filter(x=>x.id!==m?.id),finished=new Set(state.progress.filter(x=>x.status==='completed').map(x=>x.mission_id));const next=candidates.find(x=>!finished.has(x.id))||candidates[0];return `<span class="tag">Task complete</span><h1>Well done for practising.</h1><p class="sub">You completed the guided steps for ${esc(m?.title)}. This records practice, not mastery or an SFI grade.</p>${state.feedback?`<div class="card"><strong>Feedback</strong><p class="small">${esc(state.feedback)}</p></div>`:''}${error()}<div class="card"><strong>Keep going</strong><p class="small">Try a different task in this situation or revisit this conversation.</p>${next?`<button class="btn" data-mission="${esc(next.id)}">Try ${esc(next.title)}</button>`:''}<button class="btn secondary" data-action="followup">Read, write and remember</button><button class="btn secondary" data-action="retry">Try again with different words</button><button class="btn line" data-action="library">Browse situations</button></div>`}
function history(){return `<div class="eyebrow">Your practice</div><h1>Pick up where you left off.</h1><p class="sub">Completed tasks show what you practised. They are not official assessments.</p>${error()}${state.sessions.length?state.sessions.map(s=>`<div class="outline"><div class="split"><strong>${esc(s.snapshot?.mission?.title||s.mission_id)}</strong><span class="tag neutral">${s.status==='completed'?'Completed':'In progress'}</span></div><p class="small">${esc(s.snapshot?.situation?.title||s.situation_id||'')} · ${esc(s.updated_at?new Date(s.updated_at*1000).toLocaleDateString():'')}</p>${evidenceDetails(s)}${(s.phrases||[]).length?`<details><summary>Saved phrases (${s.phrases.length})</summary>${s.phrases.map(p=>`<p><b lang="sv">${esc(p.sv)}</b><br><span class="small">${esc(p.en)}</span></p>`).join('')}<p class="small">Try it elsewhere: ${esc(s.snapshot?.mission?.recall?.transfer_en||'Use a phrase in a new situation.')}</p><label class="field">Your recall<textarea data-answer="recall-${esc(s.id)}">${esc(state.answers['recall-'+s.id]||'')}</textarea></label><button class="pill" data-history-recall="${esc(s.id)}">Save recall</button></details>`:''}<div class="actions"><button data-resume="${esc(s.id)}">${s.status==='completed'?'Review':'Resume'}</button><button data-delete="${esc(s.id)}">Delete</button></div></div>`).join(''):'<div class="card empty"><strong>No saved practice yet</strong><p class="small">Choose a situation to begin.</p><button class="btn secondary" data-action="library">Browse situations</button></div>'}${state.legacySessions.length?`<h2>Earlier practice</h2><p class="small">Imported records are retained as read-only history.</p>${state.legacySessions.map(s=>`<div class="outline"><strong>${esc(s.snapshot?.scenario?.title||s.scenario_id||'Earlier session')}</strong>${evidenceDetails(s)}</div>`).join('')}`:''}<button class="btn secondary" data-action="export">Export my practice</button>${state.sessions.length||state.legacySessions.length?'<button class="btn line" data-action="delete-all">Delete all practice</button>':''}<details class="outline"><summary><b>About SFI evidence</b></summary><p class="small">The current syllabus distinguishes listening, reading, spoken interaction, spoken production and writing. Areas without suitable recorded evidence remain unassessed. The new course-based framework applies to new education from 2027 and groups speaking with conversation. A task challenge is not an SFI course.</p><p class="source"><a href="https://syllabuswebb.skolverket.se/syllabuscw/jsp/sfi.htm" target="_blank" rel="noopener">Current syllabus</a> · <a href="https://skolfs.skolverket.se/api/document/GRUNDFORFATTNING/2026:67/pdf" target="_blank" rel="noopener">New framework</a></p></details>`}
function profile(){const p=state.profile||{};return `<div class="eyebrow">Your account</div><h1>${esc(state.user?.username||'Account')}</h1><p class="sub">SFI settings are optional. Use the course and framework that apply to your education; ask your teacher if unsure.</p>${error()}<div class="outline"><label class="field">Framework<select id="framework"><option value="">Not selected</option><option value="SKOLFS-2017-91-consolidated" ${p.framework_id==='SKOLFS-2017-91-consolidated'?'selected':''}>Current consolidated syllabus</option><option value="SKOLFS-2026-67" ${p.framework_id==='SKOLFS-2026-67'?'selected':''}>2026:67 course framework</option></select></label><label class="field">Course<input id="course" value="${esc(p.course||p.selection?.course_input||'')}" placeholder="For example, 2B"></label><label class="field">Study path<select id="study-path"><option value="">Not selected</option>${[1,2,3].map(n=>`<option value="${n}" ${String(p.study_path||'')===String(n)?'selected':''}>${n}</option>`).join('')}</select></label><button class="btn" data-action="save-profile">Save settings</button><p class="tiny">Settings apply to new sessions. Existing evidence retains its original framework.${p.selection?.status==='unverified'?' This course selection is unverified and will not create criterion evidence.':''}</p></div><details class="outline"><summary><b>Data &amp; privacy</b></summary><p class="small">Speech is processed on this VPS. Recordings are deleted after processing. Your account stores transcripts, practice and history.</p><p class="small">There is no ad tracking or paid cloud AI. Deletion applies immediately to the active service. Managed encrypted backups use seven-day retention; offline copies are removed on their next sync.</p><div class="actions"><button data-action="export">Export my data</button><button data-action="delete-all">Delete all practice</button></div></details><button class="btn secondary" data-action="recovery-codes">Regenerate recovery codes</button><button class="btn secondary" data-action="logout">Sign out</button><button class="btn line" data-action="delete-account">Delete account</button>`}
function latestAnswer(activity){const records=state.session?.evidence||[];for(let i=records.length-1;i>=0;i--)if(records[i].activity===activity)return records[i];return null}
function answerReview(activity,ideas=[],reveal=false){const latest=latestAnswer(activity);const showIdeas=(latest||reveal)&&Array.isArray(ideas)&&ideas.length;return `${latest?`<div class="saved-review"><strong>Saved answer</strong><p class="small saved-answer">${esc(latest.response)}</p></div>`:''}${showIdeas?`<div class="saved-review"><strong>Compare your answer</strong><ul class="small">${ideas.map(idea=>`<li>${esc(idea)}</li>`).join('')}</ul></div>`:''}`}
function followup(){const m=state.mission;if(!m)return '';return `<button class="back" data-action="complete">← Completed task</button><div class="eyebrow">Keep practising</div><h1>Read, write, remember.</h1><p class="sub">Use this situation in another way.</p>${error()}<div class="card"><span class="eyebrow">Listen</span>${m.listening?.context_en?`<p class="small">${esc(m.listening.context_en)}</p>`:''}<p class="small">Listen first; reveal the words if you need them.</p><div class="actions"><button data-action="listen-followup">▶ Play Swedish</button><button data-action="reveal-listening">${state.listenRevealed?'Hide text':'Reveal text'}</button></div>${state.listenRevealed?`<p lang="sv">${esc(m.listening?.prompt_sv)}</p>`:''}<strong>${esc(m.listening?.question_en)}</strong><label class="field">Your answer<textarea data-answer="listening">${esc(state.answers.listening||'')}</textarea></label><button class="btn secondary" data-evidence="listening">Save listening</button>${answerReview('listening',m.listening?.answer_ideas_en,state.listenRevealed)}</div><div class="outline"><span class="eyebrow">Read</span>${m.reading?.context_en?`<p class="small">${esc(m.reading.context_en)}</p>`:''}<p lang="sv">${esc(m.reading?.text_sv)}</p><strong>${esc(m.reading?.question_en)}</strong><label class="field">Your answer<textarea data-answer="reading">${esc(state.answers.reading||'')}</textarea></label><button class="btn secondary" data-evidence="reading">Save reading</button>${answerReview('reading',m.reading?.answer_ideas_en)}</div><div class="card"><span class="eyebrow">Write</span><p>${esc(m.writing?.prompt_en)}</p><p class="small" lang="sv">${esc(m.writing?.prompt_sv)}</p>${m.writing?.starter_sv?`<p class="small" lang="sv">Starter: ${esc(m.writing.starter_sv)}</p>`:''}<label class="field">Your message<textarea data-answer="writing" placeholder="${esc(m.writing?.starter_sv)}">${esc(state.answers.writing||'')}</textarea></label><button class="btn secondary" data-evidence="writing">Save writing</button>${answerReview('writing')}</div><div class="outline"><span class="eyebrow">Recall somewhere new</span><p>${esc(m.recall?.prompt_en)}</p><label class="field">Your response<textarea data-answer="recall">${esc(state.answers.recall||'')}</textarea></label><button class="btn secondary" data-evidence="recall">Save recall</button>${answerReview('recall')}</div><div class="card"><strong>Keep a useful phrase</strong>${(m.phrases||[]).map(p=>`<div class="split"><span><b lang="sv">${esc(p.sv)}</b><br><span class="small">${esc(p.en)}</span></span><button class="pill" data-phrase="${esc(p.id)}">Save</button></div>`).join('')}</div>`}
function evidenceDetails(s){const snapshot=s.snapshot,criteria=snapshot?.criteria,links=snapshot?.criterion_links;if(!Array.isArray(criteria)||!Array.isArray(links))return '<p class="tiny">SFI criterion evidence unassessed; no saved curriculum snapshot.</p>';const turns=(s.turns||[]).filter(t=>t.role==='user'&&t.input_mode==='voice'),listening=(s.evidence||[]).filter(e=>e.activity==='listening');const voice=turns.filter(t=>t.transcript_edited===false),heard=listening.filter(e=>!(e.help_used||[]).some(h=>h==='text revealed'||h==='answer key shown'));const attempts=a=>a==='dialogue'?voice:a==='listening'?heard:(s.evidence||[]).filter(e=>e.activity===a);const matched=links.filter(l=>attempts(l.activity).length).map(l=>({l,c:criteria.find(c=>c.id===l.criterion_id&&c.framework_id===l.framework_id)})).filter(x=>x.c);let out=matched.map(({l,c})=>`<p class="source"><b>${esc(c.label||c.domain)}</b> · ${attempts(l.activity).some(a=>!(a.help_used||[]).length&&!a.clarified&&!a.confirmed_intent_id)?'Independent':'Supported'} partial practice<br>${esc(c.summary_en)}<br>${esc(l.limitation)} <a href="${esc(safeLink(c.source?.url))}" target="_blank" rel="noopener">Source</a></p>`).join('');if(listening.length&&!heard.length)out+='<p class="small">Listening domain unassessed: text or answer guidance was revealed.</p>';if(turns.length&&!voice.length)out+='<p class="small">Oral domain unassessed: transcript was edited or its edit history is unknown.</p>';return `<details><summary>Practice evidence and support</summary><p class="tiny">Framework: ${esc(snapshot?.selection?.framework_id||s.framework_id||'not selected')} · Course: ${esc(snapshot?.selection?.course||snapshot?.selection?.course_input||s.course||'not selected')}${snapshot?.selection?.status==='unverified'?' (unverified)':''} · Version: ${esc(snapshot?.curriculum_content_version||snapshot?.content_version||'unknown')}</p>${(s.turns||[]).filter(t=>t.role==='user').map(t=>`<p class="small">${esc(t.input_mode==='voice'?(t.transcript_edited?'Spoken, transcript edited':'Spoken, reviewed transcript'):'Typed')}: ${esc(t.text)} · Support: ${esc(displaySupports(t.help_used))}${confirmedMeaning(s,t)?` · Learner-confirmed meaning: ${esc(confirmedMeaning(s,t))}`:''}</p>`).join('')}${(s.evidence||[]).map(e=>`<p class="small">${esc(cap(e.activity))}: ${esc(e.response)} · Support: ${esc(displaySupports(e.help_used))}</p>`).join('')}${out||'<p class="small">No matching criterion evidence recorded; areas remain unassessed.</p>'}</details>`}
async function saveEvidence(activity){const draft=state.answers[activity]||'',response=draft.trim();if(!response){state.error='Write an answer before saving.';render();return}if(activity==='listening'&&!state.listenPlays){state.error='Play the audio before saving listening practice.';render();return}const sid=state.session.id,help_used=activity==='listening'?[...(state.listenHelp?['text revealed']:[]),...((state.listenHelp||latestAnswer('listening'))?['answer key shown']:[]),...(state.listenPlays>1?['audio replay']:[])]:activity==='writing'&&state.mission?.writing?.starter_sv?['phrase starter available']:activity==='recall'?['phrase available on page']:[],payload={activity,response,help_used},key=`evidence:${sid}:${activity}`;await run(async()=>{const d=await post(`api/missions/${encodeURIComponent(sid)}/evidence`,{...payload,request_id:requestId(key,payload)});if(state.session?.id!==sid)return;ids.delete(key);state.session=d.session;if(state.answers[activity]===draft)state.answers[activity]='';state.notice=cap(activity)+' saved.'})}
async function saveHistoryRecall(sid){const keyName='recall-'+sid,draft=state.answers[keyName]||'',response=draft.trim();if(!response){state.error='Write a recall response before saving.';render();return}const payload={activity:'recall',response,help_used:['phrase visible']},key=`evidence:${sid}:recall`;await run(async()=>{await post(`api/missions/${encodeURIComponent(sid)}/evidence`,{...payload,request_id:requestId(key,payload)});ids.delete(key);if(state.answers[keyName]===draft)state.answers[keyName]='';const d=await api('api/missions');state.sessions=d.sessions||[];state.notice='Recall saved.'})}
async function savePhrase(id){const p=(state.mission.phrases||[]).find(p=>p.id===id);if(!p)return;const sid=state.session.id,payload={sv:p.sv,en:p.en},key=`phrase:${sid}:${id}`;await run(async()=>{const d=await post(`api/missions/${encodeURIComponent(sid)}/phrases`,{...payload,request_id:requestId(key,payload)});if(state.session?.id!==sid)return;ids.delete(key);state.session=d.session;state.notice='Phrase saved.'})}
async function boot(){try{const a=await api('api/auth/session');if(!a.authenticated){authView();return}state.user=a.user;state.ownerId=a.user?.id||null;state.csrf=a.csrf;await loadData()}catch(e){state.error=e.message;render()}}
function upsertProgress(session){if(!session?.id||!session.mission_id||!['in_progress','completed'].includes(session.status))return;const item={id:session.id,mission_id:session.mission_id,status:session.status,updated_at:session.updated_at};const revision=++state.progressRevision;state.progressChanges.set(item.id,{revision,item});state.progress=[item,...state.progress.filter(x=>x.id!==item.id)]}
function removeProgress(id){const revision=++state.progressRevision;state.progressChanges.set(id,{revision,item:null});state.progress=state.progress.filter(x=>x.id!==id)}
function clearProgress(){state.progressClearRevision=++state.progressRevision;state.progressChanges.clear();state.progress=[]}
function applyProgressSnapshot(sessions,revision,sequence){if(sequence<state.progressAppliedSequence)return;state.progressAppliedSequence=sequence;const merged=new Map((state.progressClearRevision>revision?[]:sessions).filter(x=>x?.id&&x.mission_id&&['in_progress','completed'].includes(x.status)).map(x=>[x.id,{id:x.id,mission_id:x.mission_id,status:x.status,updated_at:x.updated_at}]));for(const [id,change] of state.progressChanges)if(change.revision>revision){if(change.item)merged.set(id,change.item);else merged.delete(id)}state.progress=[...merged.values()]}
async function loadData(){const epoch=state.ownerEpoch,revision=state.progressRevision,sequence=++state.progressFetchSequence;const [libraryData,profileData,progressData]=await Promise.all([api('api/library'),api('api/profile'),api('api/progress')]);if(epoch!==state.ownerEpoch)throw new DOMException('Stopped waiting','AbortError');state.situations=libraryData.situations||[];state.profile=profileData.profile||{};applyProgressSnapshot(progressData.sessions||[],revision,sequence);render()}
async function startMission(id){const mission=(state.situation?.missions||[]).find(m=>m.id===id);if(!mission)return;stopAudio();const payload={mission_id:id,framework_id:state.profile.framework_id||'',course:state.profile.course||state.profile.selection?.course_input||'',study_path:state.profile.study_path||state.profile.selection?.study_path_input||''};const key=`start:${id}`;await run(async()=>{const d=await post('api/missions',{...payload,request_id:requestId(key,payload)});ids.delete(key);state.mission=mission;state.session=d.session;upsertProgress(d.session);state.sessions=[d.session,...state.sessions.filter(x=>x.id!==d.session.id)];state.transcript='';state.originalTranscript='';state.voiceEdited=false;state.pendingAudio=null;state.support=[];state.hint=false;state.english=false;state.feedback='';state.unmatched=null;state.taskDetailsOpen=false;state.answers={};state.listenHelp=false;state.listenRevealed=false;state.listenPlays=0;state.page='practice'})}
async function resume(id){stopAudio();await run(async()=>{const d=await api(`api/missions/${encodeURIComponent(id)}`);state.session=d.session;upsertProgress(d.session);state.mission=d.session.snapshot?.mission;state.situation=state.situations.find(s=>s.id===d.session.situation_id)||d.session.snapshot?.situation;if(!state.mission)throw Error('This saved session has no mission snapshot.');state.transcript='';state.originalTranscript='';state.voiceEdited=false;state.pendingAudio=null;state.support=[];state.feedback='';state.unmatched=unmatchedMarker(d.session);state.taskDetailsOpen=false;state.answers={};state.listenHelp=false;state.listenRevealed=false;state.listenPlays=0;state.page=d.session.status==='completed'?'complete':'practice'})}
async function send(){const draft=state.transcript,text=draft.trim();if(!text){state.error='Add your words before sending.';render();return}const sid=state.session.id;const payload={text,input_mode:state.originalTranscript?'voice':'text',transcript_edited:!!(state.originalTranscript&&(state.voiceEdited||text!==state.originalTranscript.trim())),help_used:[...new Set([...state.support,...(state.hint?['hint','phrase starter']:[]),...(state.english?['english']:[])])]};const key=`turn:${sid}`;await run(async()=>{const d=await post(`api/missions/${encodeURIComponent(sid)}/turn`,{...payload,request_id:requestId(key,payload)});if(state.session?.id!==sid)return;ids.delete(key);state.session=d.session;upsertProgress(d.session);state.sessions=[d.session,...state.sessions.filter(x=>x.id!==d.session.id)];state.feedback=d.feedback||'';state.unmatched=d.matched===false&&d.session.status!=='completed'?(unmatchedMarker(d.session)||{session:sid,step:d.session.current_step,turnIndex:null,ownerEpoch:state.ownerEpoch}):null;state.scrollAfterTurn=d.session.status!=='completed';if(state.transcript===draft)state.transcript='';state.originalTranscript='';state.voiceEdited=false;state.support=[];if(d.session.status==='completed')state.page='complete'})}
async function confirmMeaning(intentId,marker){const session=state.session;if(!validUnmatched(marker,session)||!Number.isInteger(marker.turnIndex)||marker.turnIndex<0)return;const fresh=unmatchedMarker(session);if(!fresh||fresh.turnIndex!==marker.turnIndex||fresh.turnId!==marker.turnId)return;const intent=session.snapshot?.mission?.steps?.find(x=>x.id===marker.step)?.intents?.find(x=>x.id===intentId&&x.meaning_en&&x.meaning_sv);if(!intent)return;const sid=session.id,payload={step_id:marker.step,intent_id:intent.id,turn_index:marker.turnIndex,turn_id:marker.turnId},key=`clarify:${sid}:${marker.turnId}`;await run(async()=>{let d;try{d=await post(`api/missions/${encodeURIComponent(sid)}/clarify`,{...payload,request_id:requestId(key,payload)})}catch(e){if(e.status===409)throw Error('This task changed elsewhere. Open My practice and resume it to continue.');throw e}if(!validUnmatched(marker,state.session)||state.unmatched?.turnIndex!==marker.turnIndex||state.unmatched?.turnId!==marker.turnId)return;ids.delete(key);state.session=d.session;upsertProgress(d.session);state.sessions=[d.session,...state.sessions.filter(x=>x.id!==d.session.id)];state.unmatched=null;state.feedback=d.feedback||'';state.scrollAfterTurn=d.session.status!=='completed';if(d.session.status==='completed')state.page='complete'})}
async function mic(){if(state.recorder){state.recorder.stop();return}if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){state.error='Microphone needs a supported browser and HTTPS. You can type your answer.';render();return}try{const sessionId=state.session?.id,page=state.page;const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(state.session?.id!==sessionId||state.page!==page){stream.getTracks().forEach(t=>t.stop());return}state.stream=stream;const recorder=new MediaRecorder(stream),chunks=[];state.recorder=recorder;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{clearTimeout(state.recordingTimer);stream.getTracks().forEach(t=>t.stop());if(recorder.discard)return;state.recorder=null;state.stream=null;if(recorder.timedOut){state.error='Recording stopped after three minutes. Try a shorter recording or type.';render();return}state.pendingAudio=new Blob(chunks,{type:recorder.mimeType});await transcribe()};recorder.start();state.recordingTimer=setTimeout(()=>{if(state.recorder===recorder){recorder.timedOut=true;recorder.stop()}},180000);render()}catch(e){state.stream?.getTracks().forEach(t=>t.stop());state.stream=null;state.recorder=null;state.error=`Microphone unavailable: ${e.message}. You can type instead.`;render()}}
async function transcribe(){const audio=state.pendingAudio;if(!audio)return;await run(async()=>{const job=crypto.randomUUID();state.audioJob=job;let d;try{d=await api('api/transcribe',{method:'POST',headers:{'Content-Type':audio.type,'X-Audio-Job':job},body:audio})}finally{if(state.audioJob===job)state.audioJob=null}if(!d.text)throw Error('No words were recognised. Try again or type your answer.');state.transcript=d.text;state.originalTranscript=d.text;state.voiceEdited=false;state.pendingAudio=null})}
function playCached(){const audio=state.audio,epoch=state.ownerEpoch,signal=state.operation?.controller.signal;if(!audio)return Promise.resolve(false);try{audio.currentTime=0;const result=audio.play();return Promise.resolve(result).then(()=>{if(state.audio!==audio||state.ownerEpoch!==epoch||signal?.aborted)return false;state.audioNeedsTap=false;state.audioPlaying=true;if(state.audioKind==='listening')state.listenPlays=(state.listenPlays||0)+1;render();return true},e=>{if(state.audio!==audio||state.ownerEpoch!==epoch||signal?.aborted)return false;if(e?.name==='NotAllowedError'){state.audioNeedsTap=true;state.audioPlaying=false;render();return false}stopAudio();state.error='Audio could not be played on this device.';render();return false})}catch(e){if(state.audio===audio&&state.ownerEpoch===epoch){if(e?.name==='NotAllowedError'){state.audioNeedsTap=true;state.audioPlaying=false}else{stopAudio();state.error='Audio could not be played on this device.'}render()}return Promise.resolve(false)}}
async function speak(text,slow=false,kind='conversation'){stopAudio();const epoch=state.ownerEpoch,signal=state.operation?.controller.signal;const job=crypto.randomUUID();state.audioJob=job;let r;try{r=await request('api/speech',{method:'POST',headers:{'Content-Type':'application/json','X-Audio-Job':job},body:JSON.stringify({text,slow})})}finally{if(state.audioJob===job)state.audioJob=null}if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(d.error||d.detail||'Swedish audio is unavailable.')}const blob=await r.blob();if(signal?.aborted||epoch!==state.ownerEpoch)throw new DOMException('Stopped waiting','AbortError');const url=URL.createObjectURL(blob),audio=new Audio(url);state.audio=audio;state.audioUrl=url;state.audioKind=kind;state.audioNeedsTap=false;state.audioPlaying=false;audio.onended=()=>{if(state.audio===audio&&state.ownerEpoch===epoch){state.audioPlaying=false;render()}};audio.onerror=()=>{if(state.audio===audio&&state.ownerEpoch===epoch){stopAudio();state.error='Audio could not be played on this device.';render()}};await playCached();if(signal?.aborted||epoch!==state.ownerEpoch){if(state.audio===audio)stopAudio();throw new DOMException('Stopped waiting','AbortError')}}
async function loadHistory(){await run(async()=>{const d=await api('api/missions');const legacy=await api('api/legacy');state.sessions=d.sessions||[];state.legacySessions=legacy.sessions||[];state.page='history'})}
async function saveProfile(){const payload={framework_id:document.querySelector('#framework').value,course:document.querySelector('#course').value.trim(),study_path:document.querySelector('#study-path').value};state.profile={...payload};await run(async()=>{const d=await api('api/profile',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});state.profile=d.profile;state.notice='Settings saved for new sessions.'})}
async function exportData(){await run(async()=>{const auth=await api('api/auth/session');if(!auth.authenticated){state.user=null;state.authMode='login';state.authError='Your session ended. Sign in and retry the export.';authView();return}if(!auth.user?.id||auth.user.id!==state.ownerId){clearAccount();state.authMode='login';state.authError='Your account session changed. Sign in and retry the export.';authView();return}const a=document.createElement('a');a.href='api/export';a.download='prata-practice.json';a.click()})}
async function removeSession(id){if(!confirm('Delete this saved task and its practice evidence from the active service now? Managed backups use seven-day retention; offline copies are removed on their next sync.'))return;await run(async()=>{await api(`api/missions/${encodeURIComponent(id)}`,{method:'DELETE'});state.sessions=state.sessions.filter(s=>s.id!==id);removeProgress(id);if(state.session?.id===id)state.session=null})}
async function deleteAll(){if(!confirm('Delete all saved practice from the active service now? Managed backups use seven-day retention; offline copies are removed on their next sync. This cannot be undone.'))return;await run(async()=>{await api('api/missions',{method:'DELETE'});state.sessions=[];state.legacySessions=[];clearProgress();state.session=null})}
function invalidateRequests(){state.ownerEpoch++;state.operation?.controller.abort();state.operation=null;state.busy=false;stopAudio()}
function clearAccount(){invalidateRequests();stopCapture();stopAudio();ids.clear();state.query='';state.level='all';state.hint=false;state.english=false;state.user=null;state.ownerId=null;state.csrf='';state.sessions=[];state.legacySessions=[];state.progress=[];state.progressRevision=0;state.progressClearRevision=0;state.progressFetchSequence=0;state.progressAppliedSequence=0;state.progressChanges=new Map();state.session=null;state.situation=null;state.mission=null;state.profile={};state.answers={};state.transcript='';state.originalTranscript='';state.voiceEdited=false;state.pendingAudio=null;state.support=[];state.feedback='';state.unmatched=null;state.error='';state.notice='';state.recoveryCodes=[];state.listenHelp=false;state.listenRevealed=false;state.listenPlays=0;state.page='library';render()}
async function logout(){stopCapture();stopAudio();await run(async()=>{await post('api/auth/logout',{});clearAccount();state.authMode='login';authView()})}
function accountDeleteView(){dialog.querySelector('#auth-content').innerHTML='<form id="delete-account-form"><h2 id="auth-title">Delete account</h2><p class="notice">This deletes your account and practice from the active service now. Managed backups use seven-day retention; offline copies are removed on their next sync. Export first if you want a copy.</p><label class="field">Confirm with your password<input name="password" type="password" autocomplete="current-password" required></label><p id="delete-error" class="small error" role="status"></p><button class="btn" type="submit">Permanently delete account</button><button type="button" class="btn secondary" data-action="close-dialog">Cancel</button></form>';dialog.showModal()}
function recoveryCodesView(){dialog.querySelector('#auth-content').innerHTML='<form id="regenerate-form"><h2 id="auth-title">Regenerate recovery codes</h2><p class="notice">Generating new codes immediately invalidates all previous codes. Save the new codes somewhere safe.</p><label class="field">Confirm with your password<input name="password" type="password" autocomplete="current-password" required></label><p id="regenerate-error" class="small error" role="status"></p><button class="btn" type="submit">Generate new codes</button><button type="button" class="btn secondary" data-action="close-dialog">Cancel</button></form>';dialog.showModal()}
document.addEventListener('toggle',e=>{if(e.target.id==='task-details')state.taskDetailsOpen=e.target.open},true);
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){state.query=t.value;const pos=t.selectionStart;render();const f=document.querySelector('#search');f?.focus();f?.setSelectionRange(pos,pos)}if(t.id==='transcript'){state.transcript=t.value;if(state.originalTranscript&&t.value!==state.originalTranscript)state.voiceEdited=true}if(t.dataset.answer)state.answers[t.dataset.answer]=t.value});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a==='cancel'){cancel();return}if(a==='stop-audio'){stopAudio();render();return}if(a==='play-cached'){playCached();return}if(a==='close-dialog'){dialog.close();return}if(a==='recovery-done'){state.recoveryCodes=[];dialog.close();await loadData();return}if(b.dataset.authMode){if(state.authBusy)return;state.authMode=b.dataset.authMode;state.authError='';authView();return}if(state.busy)return;if(b.dataset.nav){stopCapture();stopAudio();if(b.dataset.nav==='history')await loadHistory();else go(b.dataset.nav);return}if(b.dataset.level){state.level=b.dataset.level;render();return}if(b.dataset.situation){state.situation=state.situations.find(s=>s.id===b.dataset.situation);go('situation');return}if(b.dataset.mission){await startMission(b.dataset.mission);return}if(b.dataset.resume){await resume(b.dataset.resume);return}if(b.dataset.delete){await removeSession(b.dataset.delete);return}if(b.dataset.historyRecall){await saveHistoryRecall(b.dataset.historyRecall);return}if(b.dataset.evidence){await saveEvidence(b.dataset.evidence);return}if(b.dataset.phrase){await savePhrase(b.dataset.phrase);return}if(b.dataset.confirmIntent!==undefined){const marker=state.unmatched,session=state.session;if(!validUnmatched(marker,session)||b.dataset.confirmSession!==session.id||b.dataset.confirmStep!==session.current_step||b.dataset.confirmTurn!==String(marker.turnIndex)||b.dataset.confirmTurnId!==marker.turnId||b.dataset.confirmEpoch!==String(state.ownerEpoch))return;await confirmMeaning(b.dataset.confirmIntent,marker);return}if(b.dataset.guidanceIndex!==undefined){const marker=state.unmatched,session=state.session;if(!marker||!session||state.page!=='practice'||marker.session!==session.id||marker.step!==session.current_step||marker.ownerEpoch!==state.ownerEpoch||b.dataset.guidanceSession!==session.id||b.dataset.guidanceStep!==session.current_step||b.dataset.guidanceEpoch!==String(state.ownerEpoch))return;const phrase=suggestedPhrases(session)[Number(b.dataset.guidanceIndex)];if(!phrase)return;state.transcript=phrase;state.originalTranscript='';state.voiceEdited=false;if(!state.support.includes('suggested phrase'))state.support.push('suggested phrase');render();return}if(b.dataset.speak!==undefined){const t=state.session.turns[Number(b.dataset.speak)];const support=b.dataset.slow==='true'?'slow audio':'replay';if(!state.support.includes(support))state.support.push(support);await run(()=>speak(t.text,b.dataset.slow==='true'));return}switch(a){case'library':go('library');break;case'complete':go('complete');break;case'situation':go('situation');break;case'retry':await startMission(state.mission.id);break;case'followup':go('followup');break;case'listen-followup':await run(()=>speak(state.mission.listening.prompt_sv,false,'listening'));break;case'reveal-listening':state.listenRevealed=!state.listenRevealed;if(state.listenRevealed)state.listenHelp=true;render();break;case'mic':await mic();break;case'transcribe':await transcribe();break;case'send':await send();break;case'hint':state.hint=!state.hint;if(state.hint&&!state.support.includes('hint'))state.support.push('hint');render();break;case'english':state.english=!state.english;if(state.english&&!state.support.includes('english'))state.support.push('english');render();break;case'save-profile':await saveProfile();break;case'logout':await logout();break;case'export':await exportData();break;case'delete-all':await deleteAll();break;case'delete-account':accountDeleteView();break;case'recovery-codes':recoveryCodesView();break;}});
dialog.addEventListener('cancel',e=>{if(!state.user||state.recoveryCodes.length)e.preventDefault()});
dialog.addEventListener('submit',async e=>{e.preventDefault();if(state.authBusy)return;state.authBusy=true;const f=e.target,form=new FormData(f),password=String(form.get('password')||'');const input=f.querySelector('[name=password]');if(input)input.value='';const btn=f.querySelector('[type=submit]');btn.disabled=true;try{if(f.id==='regenerate-form'){const d=await post('api/auth/recovery-codes',{password});if(!Array.isArray(d.recovery_codes)||!d.recovery_codes.length)throw Error('No codes were returned.');showRecovery(d.recovery_codes);return}if(f.id==='delete-account-form'){await api('api/account',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});clearAccount();dialog.close();state.authMode='login';state.authError='Account deleted.';authView();return}const mode=state.authMode,payload={username:String(form.get('username')||''),password};if(mode==='register')payload.invite=String(form.get('invite')||'');if(mode==='recover'){payload.recovery_code=String(form.get('recovery_code')||'');payload.new_password=password;delete payload.password}const r=await fetch(`api/auth/${mode==='recover'?'recover':mode}`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),cache:'no-store'}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||d.detail||'Unable to sign in.');if(mode==='recover'){state.authMode='login';state.authError='Password reset. Sign in with your new password.';authView();return}if(!d.user?.username)throw Error('Sign-in response did not identify an account.');const nextOwner=d.user.id||null;if(!nextOwner||state.ownerId!==nextOwner)clearAccount();else invalidateRequests();state.ownerId=nextOwner;state.user=d.user;state.csrf=d.csrf;state.authError='';if(d.recovery_codes?.length)showRecovery(d.recovery_codes);else{dialog.close();await loadData()}}catch(err){if(f.id==='delete-account-form')document.querySelector('#delete-error').textContent=err.message;else if(f.id==='regenerate-form')document.querySelector('#regenerate-error').textContent=err.message;else{state.authError=err.message;authView()}}finally{state.authBusy=false;btn.disabled=false}});
boot();
